/**
 * Advance widths for the six PDF base-14 faces the exporter uses, in 1/1000 em.
 *
 * Base-14 fonts are the ones every PDF reader already has, so nothing has to be
 * embedded and the files stay a few kB. The trade is that the exporter has to
 * know their metrics to wrap a line, and it has to know them the same way on
 * every machine — measuring the reader's own fonts at download time would let
 * the same record paginate differently depending on who exported it.
 *
 * Generated by measuring the genuine Adobe faces, then checked against the
 * published AFM values (see tests). Do not hand-edit: each entry is a palette of
 * the distinct widths in the face plus one index character per code point from
 * 32 to 255, which is what keeps the whole table under 2 kB.
 */
export interface FontWidths {
  palette: number[];
  indices: string;
}

export const FIRST_CODE = 32;
export const LAST_CODE = 255;
/** Added to a palette index to keep every character printable and unescaped. */
export const INDEX_OFFSET = 40;

