/** Advance width of one WinAnsi code point, in 1/1000 em. */
export function glyphWidth(font: string, code: number): number {
  const table = FONT_WIDTHS[font];
  if (!table || code < FIRST_CODE || code > LAST_CODE) return 0;
  const index = table.indices.charCodeAt(code - FIRST_CODE) - INDEX_OFFSET;
  return table.palette[index] ?? 0;
}
